import UIKit

private let log = DebugLog.create("silk-videoplayer")

/**
 * Video player that plays DASH segments generated by Silk device
 */
public class DashSegmentPlayer : UIView, VBPlayerDelegate {

  private var bridge: RCTBridge!

  private var player: VBDataPlayer?
  private var playerLayer: VBDisplayLayer?

  private var playing = false
  private var pendingPlay: PropertyObserverKey?

  private let playback = DashSegmentPlayback()

  private let methodQueue = dispatch_queue_create("com.silklabs.videoplayer", nil)

  init(bridge: RCTBridge) {
    super.init(frame: CGRectZero)
    self.bridge = bridge
  }

  override init(frame: CGRect) {
    NOT_IMPLEMENTED()
    super.init(frame: frame)
  }

  required public init?(coder aDecoder: NSCoder) {
    NOT_IMPLEMENTED()
    super.init(coder: aDecoder)
  }

  deinit {
    self.destroy()
  }

  func destroy() {
    if let player = self.player {
      player.removeAllKeyPathObservers()
    }
    self.player = nil
    self.playerLayer = nil
    self.bridge = nil
  }

  private func initializePlayerAndPlay() {
    self.playerLayer = VBDisplayLayer()
    self.playerLayer!.frame = self.bounds
    self.layer.addSublayer(self.playerLayer!)

    self.player = VBDataPlayer.createDataPlayer()
    self.player!.delegate = self
    self.player!.setDisplayLayer(self.playerLayer!)

    // TODO: use self.player.addPeriodicTimeObserverForInterval() and dispatch
    // time updates to React Native

    // TODO: we're currently playing dangerously close to the end of the buffer.
    // Perhaps add a slight delay and only play when enough segments have been buffered?
    self.playWhenReady()
  }

  func play() {
    log.debug("\(self.reactTag): play()")
    AssertMainThread()

    if (self.player == nil) {
      self.initializePlayerAndPlay()
      return;
    }

    if self.playing {
      return
    }

    if self.player!.status == .ReadyToPlay {
      log.debug("\(self.reactTag): play() -- ReadyToPlay")
      log.debug("bufferedDuration: \(self.player!.bufferedDuration())")
      self.playing = true
      self.pendingPlay = nil
      self.player!.play()
      return
    }

    if self.player!.status == .Failed {
      log.debug("\(self.reactTag): play() -- Failed \(self.player!.error)")
      // TODO: dispatch event to JS
    }

    self.playWhenReady()
  }

  func playWhenReady() {
    log.debug("\(self.reactTag): playWhenReady()")

    // If the player is not ready yet we must wait for it to be in a ready state.
    log.debug("\(self.reactTag): play() -- !ReadyToPlay \(self.player!.status.rawValue)")
    self.pendingPlay = self.player!.observeKeyPath("status") {
      [unowned self]
      (kvo, _) in

      log.debug("\(self.reactTag): player status change \(self.player!.status.rawValue)")
      if self.player!.status == .Failed {
        log.debug("play() -- Failed \(self.player!.error)")
        // TODO: dispatch event to JS
      }
      if self.player!.status != .ReadyToPlay {
        return
      }
      dispatch_async(dispatch_get_main_queue()) {
        self.play()
        self.player!.removeKeyPathObserver(kvo)
      }
    }
  }

  func pause() {
    log.debug("\(self.reactTag): pause()")
    if self.playing {
      // If we are already playing a simple pause works...
      self.player!.pause()
      self.playing = false
      // Note: we _could_ reset playback rate here but that would defeat the purpose of trying
      // to give JS as much control as possible.
    } else if self.pendingPlay != nil {
      // If we are waiting to play, remove the callback.
      self.player!.removeKeyPathObserver(self.pendingPlay!)
      self.pendingPlay = nil
    }
  }

  func enqueue(segment: VideoSegment) {
    dispatch_async(self.methodQueue) {
      let blobManager = self.bridge.moduleForClass(BlobManager) as! BlobManager
      let rawData = blobManager.resolveAndReleaseBlob(segment.blob!)
      guard rawData != nil else {
        log.error("Could not resolve blob \(segment.blob!)")
        self.dispatchErrorEvent()
        return
      }
      let data: NSData
      do {
        data = try self.playback.processSegment(NSMutableData(data: rawData!))
        try self.player!.appendData(data, coding: .MP4)
      } catch {
        log.debug("processSegment() failed")
        self.dispatchErrorEvent()
        return
      }
    }
  }

  private func dispatchErrorEvent() {
    log.debug("dispatchErrorEvent()")
    // TODO: dispatch event to JS
  }

  // VBPlayerDelegate

  public func playerDidEnterStall(player: VBPlayer!) {
    log.debug("playerDidEnterStall()")
    // TODO: dispatch event to JS
  }

  public func playerDidExitStall(player: VBPlayer!) {
    log.debug("playerDidExitStall()")
    // TODO: dispatch event to JS
  }

  public func playerDidFinish(player: VBPlayer!) {
    log.debug("playerDidFinish()")
    // TODO: dispatch event to JS
  }
}